"""降低 funasr 加载权重时的内存峰值。

funasr 的 `load_pretrained_model` 在 `torch.load` 之后又 `copy.deepcopy` 了一份完整
state_dict，而原始那份之后再没被用到。SenseVoiceSmall 的 model.pt 有 936 MB，于是
加载瞬间同时存在三份权重（模型自身参数 + ori_state + 深拷贝副本），峰值约 3.0 GB，
4 GB 内存的部署板子会被 OOM killer 直接杀掉（进程无 traceback 静默退出）。

这里在建模前替换该模块引用的 copy / torch：deepcopy 退化为直传，torch.load 改走
mmap——权重页变成 file-backed，内存紧张时内核可以回收而不是杀进程。
实测峰值 3051 MB -> 2312 MB（CPU，SenseVoiceSmall），推理结果不变。
"""

import copy as _copy

import torch as _torch
from funasr.train_utils import load_pretrained_model as _lpm

_patched = False


class _NoDeepcopy:
    """只截掉 deepcopy，其余属性透传给真正的 copy 模块。"""

    @staticmethod
    def deepcopy(obj):
        return obj

    def __getattr__(self, name):
        return getattr(_copy, name)


class _MmapTorch:
    """只包装 load，其余属性透传给真正的 torch。"""

    @staticmethod
    def load(f, **kwargs):
        try:
            return _torch.load(f, mmap=True, **kwargs)
        except Exception:
            # mmap 只支持新式 zipfile 格式的 ckpt，旧格式或 BytesIO 回退原路径
            return _torch.load(f, **kwargs)

    def __getattr__(self, name):
        return getattr(_torch, name)


def patch_funasr_ckpt_loading() -> None:
    """幂等；必须在加载模型之前调用。"""
    global _patched
    if _patched:
        return
    _lpm.copy = _NoDeepcopy()
    _lpm.torch = _MmapTorch()
    _patched = True

